head.script:
scwin.jsonData1 = [
	{ "type01" : "12345678", "type02" : "12345678.12345" },
	{ "type01" : "12345678", "type02" : "12345678.12" },
	{ "type01" : "12345678", "type02" : "12345678.123" },
	{ "type01" : "12345678", "type02" : "12345678.1234" }
];
scwin.onpageload = function() {
	// 컬럼별 euro 포맷: gridView euroMask(#.###,##)와 다른 포맷을 컬럼마다 지정
	grd_sample.changeCurrency({
		colID : "type01",
		type : "euro",
		format : "#.###,#"
	});
	grd_sample.changeCurrency({
		colID : "type02",
		type : "euro",
		delimiter : ".",
		decimalDelimiter : ",",
		customModelFormatter : "scwin.inputCustomFormat",
		customModelUnformatter : "scwin.inputCustomUnFormat",
		format : "#.###,###"
	});
};
scwin.btn_search_onclick = function() {
	dlt_sample.setJSON(scwin.jsonData1);
};
scwin.inputCustomFormat = function(realData, formattedData) {
	return realData.replace(",", ".");
};
scwin.inputCustomUnFormat = function(realData, formattedData) {
	return realData.replace(".", ",");
};
